#define long long ll
#define input(a,n) for(int i=0;i<n;i++)cin>>a[i]
using namespace std;

template <class T,class L> T& maximize(T &x,L y){if(y>x)x=y;return x;}
template <class T,class L> T& minimize(T &x,L y){if(y<x)x=y;return x;}
typedef pair<ll,ll> pii;
const int MAXN=200017;
unordered_map<ll,ll> cache;
ll digit_count(ll x){
  ll count=0;
  while(x){
    count++;
    x/=10;
  }
  return count;
}
ll reverse_transform(ll x){
  ll digits[17],p=0;
  while(x){
    digits[p++]=(x%10)-(x<0?-1:1);
    x/=10;
  }
  ll result=0;
  while(p--){
    result*=10;
    result+=digits[p];
  }
  return result;
}
ll previous_value(ll x){
  ll c=0, temp=x;
  while(x){
    c*=10;
    c+=(x<0?-1:1);
    x/=10;
  }
  c*=10;
  c++;
  return temp - c;
}
ll last_digit(ll x){
  while(x>=10)
    x/=10;
  return x;
}
ll delete_leading(ll x){
  ll digits[17],p=0;
  while(x>=10){
    digits[p++]=x%10;
    x/=10;
  }
  ll res=0;
  while(p--){
    res=res*10+digits[p];
  }
  return res;
}
ll compute(ll x){
  if(x<=11)return min(13 - x, x);
  if(cache[x])return cache[x];
  ll n=0, t=1;
  while(t<x){
    t*=10;
    t++;
    n++;
  }
  if(x*2>=t)
    return cache[x]=min(compute(t - x)+n+1, (x/(t/10))*n+compute(x%(t/10)));
  return cache[x]=(x/(t/10))*n+compute(x%(t/10));
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll a;
  cin>>a;
  cout<<compute(a)<<'\n';
  return 0;
}
